ok = True
for page, pairs in PAGES.items():
    s = (ROOT / page).read_text()
    for es, en in pairs:
        if es not in s:
            if (es, en) in COMMON: continue
            print(f'MISSING in {page}: {es[:90]}'); ok = False; continue
        s = s.replace(es, en)
    (ROOT / 'en').mkdir(exist_ok=True)
    (ROOT / 'en' / page).write_text(s)
sys.exit(0 if ok else 1)
